package cn.dancingsnow.neoecoae.platform.forge;

import net.minecraft.client.gui.GuiScreen;

import com.gtnewhorizon.gtnhlib.config.ConfigException;
import com.gtnewhorizon.gtnhlib.config.SimpleGuiConfig;
import com.gtnewhorizon.gtnhlib.config.SimpleGuiFactory;

import cn.dancingsnow.neoecoae.NeoECOAE;

/** The mod list's config button, generated by GTNHLib from the PlanningSettings categories. */
public final class PlanningSettingsGuiFactory implements SimpleGuiFactory {

    @Override
    public Class<? extends GuiScreen> mainConfigGuiClass() {
        return Screen.class;
    }

    public static final class Screen extends SimpleGuiConfig {

        public Screen(GuiScreen parent) throws ConfigException {
            super(parent, NeoECOAE.MODID, "Neo ECO AE Extension", PlanningSettings.CATEGORIES);
        }
    }
}
